<style>
    .event-admin{--event-ink:#112b48;--event-muted:#718096;--event-line:#e6eaf0;--event-gold:#d5aa58;color:var(--event-ink);max-width:1440px;margin:0 auto;padding:18px 2px 42px;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}
    .event-admin *{box-sizing:border-box}.event-admin .admin-h1{margin:0;color:var(--event-ink);font-size:clamp(25px,3vw,34px);font-weight:850;letter-spacing:-.045em;line-height:1.1}.event-admin .event-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin:0 0 21px}.event-admin .event-heading-copy{max-width:700px}.event-admin .event-kicker{margin:0 0 7px;color:#a77a2e;font-size:10px;font-weight:850;letter-spacing:.16em;text-transform:uppercase}.event-admin .event-subtitle{margin:7px 0 0;color:var(--event-muted);font-size:13px;line-height:1.6}.event-admin .event-panel{border:1px solid var(--event-line);border-radius:15px;background:#fff;box-shadow:0 6px 24px #112b4808}.event-admin .event-actions{display:flex;align-items:center;gap:8px}.event-admin .event-primary{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:42px;padding:0 16px;border:0;border-radius:9px;background:#102d4b;color:#fff;font-size:12px;font-weight:750;text-decoration:none;box-shadow:0 6px 16px #102d4b1c;transition:.18s}.event-admin .event-primary:hover{background:#1b4267;transform:translateY(-1px)}.event-admin .event-secondary{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:0 13px;border:1px solid var(--event-line);border-radius:9px;background:#fff;color:#526276;font-size:11px;font-weight:700;text-decoration:none}.event-admin .event-secondary:hover{background:#f7f8fa}.event-admin .event-card-title{color:#20344c;font-size:13px;font-weight:800}.event-admin .event-label{display:block;margin:0 0 6px;color:#34465b;font-size:11px;font-weight:750}.event-admin input:not([type=radio]):not([type=checkbox]):not([type=file]),.event-admin select,.event-admin textarea,.event-admin .tw-form-control{border-color:#dce3eb;border-radius:9px;background:#fff;color:#182a40;font-size:12px;box-shadow:none}.event-admin input:not([type=radio]):not([type=checkbox]):not([type=file]):focus,.event-admin select:focus,.event-admin textarea:focus,.event-admin .tw-form-control:focus{border-color:#c39b54;outline:0;box-shadow:0 0 0 3px #d8ad5d24}.event-admin .ev-pill,.event-admin .event-type-pill,.event-admin .schedule-pill,.event-admin .att-scope-pill{border-radius:12px!important;border-color:#e0e6ed!important;background:#fff!important;transition:.18s ease}.event-admin .ev-pill:has(input:checked),.event-admin .event-type-pill:has(input:checked),.event-admin .schedule-pill:has(input:checked),.event-admin .att-scope-pill:has(input:checked){border-color:#d0a753!important;background:#fffaf0!important;box-shadow:0 0 0 3px #d8ad5d18}.event-admin .ev-pill:hover,.event-admin .event-type-pill:hover,.event-admin .schedule-pill:hover,.event-admin .att-scope-pill:hover{border-color:#c8a25b!important;transform:translateY(-1px)}.event-admin .event-validation{padding:12px 15px;border:1px solid #f0caca;border-radius:10px;background:#fff6f6;color:#ad3838;font-size:11px}.event-admin .event-back{display:inline-flex;align-items:center;gap:7px;margin-bottom:14px;color:#748196;font-size:11px;font-weight:700;text-decoration:none}.event-admin .event-back:hover{color:#142e4b}
    .event-list .event-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:0 0 17px}.event-list .event-stat{padding:14px 16px;border:1px solid var(--event-line);border-radius:12px;background:linear-gradient(145deg,#fff,#fafbfd)}.event-list .event-stat span{display:block;color:#78879a;font-size:10px;font-weight:650}.event-list .event-stat strong{display:block;margin-top:5px;color:#183451;font-size:22px;font-weight:850;letter-spacing:-.04em}.event-list .event-stat em{display:block;margin-top:2px;color:#a0aab6;font-size:9px;font-style:normal}.event-list .event-filterbar{display:flex;align-items:center;flex-wrap:wrap;gap:8px;padding:14px;border:1px solid var(--event-line);border-radius:13px;background:#fff}.event-list .event-search{position:relative;flex:1 1 220px}.event-list .event-search i{position:absolute;left:12px;top:13px;color:#99a4b1;font-size:11px}.event-list .event-search input{width:100%;padding-left:33px!important}.event-list .event-filter-select{width:auto;min-width:145px;min-height:39px;padding:0 32px 0 11px}.event-list .event-filter-pills{display:flex;flex-wrap:wrap;gap:6px;margin:16px 0}.event-list .event-filter-pill{display:inline-flex;align-items:center;gap:7px;padding:7px 11px;border:1px solid #e4e9ef;border-radius:999px;background:#fff;color:#607084;font-size:10px;font-weight:750;text-decoration:none}.event-list .event-filter-pill.is-active{border-color:#163b5e;background:#163b5e;color:white}.event-list .event-results{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.event-list .event-card{display:grid;grid-template-columns:145px minmax(0,1fr);min-height:158px;overflow:hidden;border:1px solid var(--event-line);border-radius:13px;background:#fff;box-shadow:0 4px 15px #112b4807;transition:.18s}.event-list .event-card:hover{border-color:#d3b36e;box-shadow:0 10px 26px #112b4810;transform:translateY(-2px)}.event-list .event-card-image{position:relative;min-height:158px;overflow:hidden;background:linear-gradient(140deg,#153858,#071f37)}.event-list .event-card-image img{width:100%;height:100%;object-fit:cover}.event-list .event-card-placeholder{display:grid;width:100%;height:100%;min-height:158px;place-items:center;color:#edc875;font-size:27px}.event-list .event-card-content{min-width:0;padding:15px}.event-list .event-card-top{display:flex;align-items:flex-start;justify-content:space-between;gap:7px}.event-list .event-card h2{margin:0;color:#20344c;font-size:14px;font-weight:820;line-height:1.35}.event-list .event-badge{display:inline-flex;align-items:center;gap:5px;flex:none;padding:4px 7px;border-radius:999px;background:#eef7f1;color:#28804a;font-size:9px;font-weight:800;text-transform:capitalize}.event-list .event-badge.is-past{background:#f1f3f5;color:#758194}.event-list .event-badge.is-online{background:#eff5ff;color:#386bb0}.event-list .event-card-meta{display:grid;gap:6px;margin:10px 0;color:#68798c;font-size:10px}.event-list .event-card-meta span{display:flex;align-items:center;gap:7px;min-width:0}.event-list .event-card-meta i{width:12px;color:#b18942;text-align:center}.event-list .event-card-description{display:-webkit-box;overflow:hidden;margin:8px 0 11px;color:#8390a0;font-size:10px;line-height:1.5;-webkit-line-clamp:2;-webkit-box-orient:vertical}.event-list .event-card-footer{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:auto}.event-list .event-card-link{color:#a77a2e;font-size:10px;font-weight:800;text-decoration:none}.event-list .event-card-link:hover{color:#183451}.event-list .event-type-tag{display:inline-flex;padding:4px 7px;border-radius:999px;background:#f5f6f8;color:#68778a;font-size:9px;font-weight:750;text-transform:capitalize}.event-list .event-empty{padding:55px 20px;text-align:center}.event-list .event-empty-icon{display:grid;width:56px;height:56px;margin:0 auto 14px;place-items:center;border-radius:18px;background:#fbf4e7;color:#af8539;font-size:20px}.event-list .event-calendar-panel{padding:16px}.event-admin .event-tabs{display:flex;gap:5px;overflow-x:auto;padding:9px;border-bottom:1px solid var(--event-line);background:#fbfcfd}.event-admin .event-tabs .ev-tab-btn{border:0!important;border-radius:8px 8px 0 0;padding:12px 14px!important;font-size:11px;font-weight:750}.event-admin .event-tabs .ev-tab-btn[class*="text-blue-600"]{background:#fff;color:#173654!important;box-shadow:inset 0 -2px #d5aa58}.event-admin .event-tab-content{padding:20px}.event-admin .event-cover{max-height:330px;border-radius:12px;object-fit:cover}.event-admin .event-detail-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px}.event-admin .event-detail-item{padding:13px;border:1px solid #e9edf1;border-radius:11px;background:#fcfcfd}.event-admin .event-detail-item small{display:block;margin-bottom:6px;color:#8b97a5;font-size:9px;font-weight:750;letter-spacing:.08em;text-transform:uppercase}.event-admin .event-detail-item strong{display:block;color:#33475e;font-size:11px;font-weight:750;line-height:1.5;overflow-wrap:anywhere}
    @media(max-width:1100px){.event-list .event-results{grid-template-columns:1fr}.event-list .event-card{grid-template-columns:160px minmax(0,1fr)}}
    @media(max-width:700px){.event-admin{padding:12px 0 30px}.event-admin .event-heading{align-items:flex-start;flex-direction:column}.event-admin .event-actions{width:100%}.event-admin .event-actions>*{flex:1}.event-list .event-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.event-list .event-filterbar{align-items:stretch}.event-list .event-search,.event-list .event-filter-select{flex:1 1 100%;width:100%}.event-list .event-card{grid-template-columns:105px minmax(0,1fr)}.event-list .event-card-content{padding:12px}.event-list .event-card-image,.event-list .event-card-placeholder{min-height:145px}.event-list .event-card h2{font-size:12px}.event-admin .event-detail-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.event-admin .event-tabs .ev-tab-btn{padding:10px!important}.event-admin .event-tab-content{padding:13px}}
    @media(max-width:430px){.event-list .event-card{grid-template-columns:1fr}.event-list .event-card-image,.event-list .event-card-placeholder{height:155px;min-height:155px}.event-list .event-card-footer{margin-top:10px}.event-admin .event-detail-grid{grid-template-columns:1fr}}
    .event-admin .event-summary>div:first-child{width:35%;min-width:240px;padding:0!important;background:#102c49!important}.event-admin .event-summary .event-cover{width:100%;height:100%;min-height:260px;max-height:360px;border-radius:0;object-fit:cover}
</style>
